"""Audit raw predictions, budgets and initialization, then summarize paired outcomes.
No seed pooling. Familywise Holm correction for predeclared C comparisons.
"""
import argparse,csv,hashlib,itertools,json,math,statistics
from pathlib import Path
from scoring_v2_v1 import is_correct,old_is_correct
SPLITS=['A_newPerson','B_newCategory','C_bothNew']
def read(p):return [json.loads(s) for s in Path(p).read_text().splitlines() if s.strip()]
def key(r):return r['category'],r['person']
def mean(v):return statistics.mean(v) if v else None
def moments(v):
 sd=statistics.stdev(v);m=mean(v);h=4.302652729911275*sd/math.sqrt(3);return {'values':v,'mean':m,'sample_sd':sd,'seed_mean_t95':[m-h,m+h]}
def paired(x,y):
 assert len(x)==len(y) and x;w=sum(a and not b for a,b in zip(x,y));l=sum(b and not a for a,b in zip(x,y));n=w+l;p=min(1.,2*sum(math.comb(n,i) for i in range(min(w,l)+1))/2**n) if n else 1.
 return {'n':len(x),'wins':w,'losses':l,'gain_pp':100*(w-l)/len(x),'mcnemar_p':p}
def holm(ts):
 prev=0.
 for i,t in enumerate(sorted(ts,key=lambda t:t['mcnemar_p'])):prev=max(prev,min(1.,(len(ts)-i)*t['mcnemar_p']));t['mcnemar_p_holm']=prev

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--runs',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();stages=json.loads((a.runs/'stages.json').read_text());assert len(stages)==21
 train=read(a.runs/'plan/train.jsonl');trkeys=list(map(key,train));assert len(set(trkeys))==len(train)
 stageby={(s['condition'],s['round'],s['seed']):s for s in stages};initial={};configs={};base={s:read(a.runs/'baseline'/f'eval_{s}.jsonl') for s in SPLITS};raw={};gold={s:{key(r):r['e'] for r in read(a.runs/'plan'/f'items_{s}.jsonl')} for s in SPLITS}
 for st in stages:
  c,r,k=st['condition'],st['round'],st['seed'];p=a.runs/st['path'];assert (p/'complete.json').exists();cfg=json.loads((p/'run_config.json').read_text());ini=json.loads((p/'initialization.json').read_text());configs[c,r,k]=cfg;initial[c,r,k]=ini
  assert cfg['condition']==c and cfg['round']==r and cfg['train_seed']==k
  assert cfg['epochs']==(2*r if c=='frozen_budget' else 2);assert cfg['optimizer_steps']==cfg['epochs']*math.ceil(len(train)/8);assert cfg['sample_exposures']==cfg['epochs']*len(train)
  assert list(map(key,read(p/'train_examples.jsonl')))==trkeys
  for s in SPLITS:
   rs=read(p/f'eval_{s}.jsonl');assert list(map(key,rs))==list(map(key,base[s]));raw[c,r,k,s]=rs
   assert all(z['composed_ok']==is_correct(z['pred'],gold[s][key(z)]['Answer']) and z['q1_ok']==is_correct(z['q1_pred'],gold[s][key(z)]['A1']) and z['q2_ok']==is_correct(z['q2_pred'],gold[s][key(z)]['A2']) for z in rs)
 for k in range(3):
  assert len({initial[c,r,k]['lora_initial_sha256'] for c,r in [('shared',1),('reset',2),('reset',3),('frozen_budget',2),('frozen_budget',3)]})==1
  for r in [2,3]:
   prev=a.runs/(f'shared_r1_s{k}' if r==2 else f'continue_r2_s{k}')/'adapter/adapter_model.safetensors';assert configs['continue',r,k]['init_adapter_sha256']==hashlib.sha256(prev.read_bytes()).hexdigest()
   # Both branches use targets generated by their own previous model (R1 is shared).
   for c in ['reset','continue']:
    tp=a.runs/(f'shared_targets_r1_s{k}' if r==2 else f'{c}_targets_r2_s{k}')/'targets.jsonl';assert configs[c,r,k]['targets_sha256']==hashlib.sha256(tp.read_bytes()).hexdigest()
    producer=a.runs/(f'shared_r1_s{k}' if r==2 else f'{c}_r2_s{k}')/'adapter/adapter_model.safetensors';td=json.loads((tp.parent/'diagnostic.json').read_text());assert td['generator_adapter_sha256']==hashlib.sha256(producer.read_bytes()).hexdigest()
   assert configs['frozen_budget',r,k]['targets_sha256']==hashlib.sha256((a.runs/'base_targets/targets.jsonl').read_bytes()).hexdigest()
 groups=[];per=[];vectors={};primary=[];hoptests=[];variants=[('shared',1),('reset',2),('reset',3),('continue',2),('continue',3),('frozen_budget',2),('frozen_budget',3)]
 for s in SPLITS:
  for metric,field in [('composed','composed_ok'),('hop1','q1_ok'),('hop2','q2_ok')]:
   b=[r[field] for r in base[s]]
   for c,r in variants:
    vals=[];gains=[];wrong=[]
    for k in range(3):
     rs=raw[c,r,k,s];v=[z[field] for z in rs];vectors[c,r,k,s,metric]=v;pv=paired(v,b);vals.append(100*mean(v));gains.append(pv['gain_pp']);bad=[z['mean_logprob'] for z in rs if not z['composed_ok'] and z['mean_logprob'] is not None];wrong.append(mean(bad));rec={'condition':c,'round':r,'seed':k,'subset':s,'metric':metric,'base_accuracy_pct':100*mean(b),'accuracy_pct':100*mean(v),**pv};per.append(rec)
     if s=='C_bothNew':(primary if metric=='composed' else hoptests).append(rec)
    groups.append({'condition':c,'round':r,'subset':s,'metric':metric,'accuracy_pct':moments(vals),'gain_pp':moments(gains),'wrong_composed_mean_logprob_by_seed':wrong if metric=='composed' else None})
 # Explicit comparisons fixed before seeing outcomes. R1 is the frozen one-round control.
 pairs=[(('reset',2),('shared',1)),(('reset',3),('shared',1)),(('reset',3),('reset',2)),(('continue',2),('shared',1)),(('continue',3),('continue',2)),(('continue',2),('frozen_budget',2)),(('continue',3),('frozen_budget',3)),(('reset',2),('frozen_budget',2)),(('reset',3),('frozen_budget',3)),(('reset',2),('continue',2)),(('reset',3),('continue',3))]
 comparisons=[]
 for x,y in pairs:
  ps=[]
  for k in range(3):
   z={'seed':k,**paired(vectors[x[0],x[1],k,'C_bothNew','composed'],vectors[y[0],y[1],k,'C_bothNew','composed'])};ps.append(z);primary.append(z)
  comparisons.append({'condition':list(x),'control':list(y),'paired_seeds':ps,'gain_pp':moments([z['gain_pp'] for z in ps])})
 assert len(primary)==54 and len(hoptests)==42
 holm(primary);holm(hoptests)
 targetdiag={}
 for p in [a.runs/'base_targets',*sorted(a.runs.glob('*_targets_r*_s*'))]:
  if p.is_dir():targetdiag[p.name]=json.loads((p/'diagnostic.json').read_text())
 sensitivity=[]
 for s in SPLITS:
  for c,r in variants:
   for k in range(3):
    rs=raw[c,r,k,s]
    sensitivity.append({'condition':c,'round':r,'seed':k,'subset':s,'legacy_pct':100*mean([old_is_correct(z['pred'],gold[s][key(z)]['Answer']) for z in rs]),'truncate_pct':100*mean([is_correct(z['pred'],gold[s][key(z)]['Answer'],'truncate') for z in rs])})
 report={'groups':groups,'per_run':per,'C_paired_comparisons':comparisons,'C_primary_test_family_n':len(primary),'C_hop_test_family_n':len(hoptests),'baseline_reference_check':json.loads((a.runs/'baseline/reference_check.json').read_text()) if (a.runs/'baseline/reference_check.json').exists() else None,'target_diagnostics':targetdiag,'score_sensitivity':sensitivity,'configurations':{'_'.join(map(str,k)):v for k,v in configs.items()},'limitations':['Repeated use of the same training people: target refresh, not new-person learning each round.','Reset final adapters receive one round of gradients; trajectories consume cumulative compute.','Continuous frozen controls have continuous LR schedules; continued branch restarts optimizer/scheduler, so the comparison does not perfectly isolate target refresh.','Three seeds and fixed evaluation split; seed t intervals assume normal seed effects.','Mean confidence on errors is conditional on a changing error set; also inspect common-error matched items.','Gold used for diagnosis only; no performance-based round selection.','Stop after exp11 and make a stage decision before exp12.']}
 # Matched items wrong at both endpoints: conditional set cannot manufacture confidence trend.
 common_errors=[]
 for c in ['reset','continue']:
  for k in range(3):
   seq=[base['C_bothNew'],raw['shared',1,k,'C_bothNew'],raw[c,2,k,'C_bothNew'],raw[c,3,k,'C_bothNew']];idx=[i for i in range(len(seq[0])) if all(not v[i]['composed_ok'] and v[i]['mean_logprob'] is not None for v in seq)];common_errors.append({'branch':c,'seed':k,'n_common_wrong':len(idx),'mean_logprob_base_R1_R2_R3':[mean([v[i]['mean_logprob'] for i in idx]) for v in seq]})
 report['common_error_confidence']=common_errors;a.out.mkdir(exist_ok=False);(a.out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2,allow_nan=False))
 with (a.out/'round_metrics.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['condition','round','subset','metric','base_pct','mean_pct','sample_sd_pp','gain_pp','seed_t95_low','seed_t95_high'])
  for g in groups:w.writerow([g['condition'],g['round'],g['subset'],g['metric'],next(x['base_accuracy_pct'] for x in per if x['subset']==g['subset'] and x['metric']==g['metric']),g['accuracy_pct']['mean'],g['accuracy_pct']['sample_sd'],g['gain_pp']['mean'],*g['gain_pp']['seed_mean_t95']])
 with (a.out/'target_quality.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['generator','n','target_correct_pct','q1_correct_pct','mean_logprob_wrong','wrong_with_score_n','null_score_n','generation_seconds'])
  for name,d in targetdiag.items():w.writerow([name,d['n'],100*d['target_correct_share'],100*d['q1_correct_share'],d['mean_logprob_wrong'],d['wrong_with_score_n'],d['null_score_n'],d['seconds']])
 lines=['EXP11 primary C results (floor; three seeds; no seed pooling):']
 for g in groups:
  if g['subset']=='C_bothNew' and g['metric']=='composed':lines.append(f"{g['condition']} R{g['round']}: {g['accuracy_pct']['mean']:.2f} +/- {g['accuracy_pct']['sample_sd']:.2f}% ; gain {g['gain_pp']['mean']:+.2f} pp")
 lines+=['All round outcomes retained. Do not select the best round on C.','Stop at this checkpoint and decide next direction with the user.'];(a.out/'report.txt').write_text('\n'.join(lines));print('\n'.join(lines),flush=True)
if __name__=='__main__':main()
